package in.sevasetu.amc.web;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController@RequestMapping("/api/admin/salespeople")@PreAuthorize("hasRole('ADMIN')")
public class AdminSalespersonController{
 private final JdbcClient db;private final PasswordEncoder passwords;public AdminSalespersonController(JdbcClient db,PasswordEncoder passwords){this.db=db;this.passwords=passwords;}
 public record Salesperson(UUID id,String username,String displayName,boolean active){}public record Create(@NotBlank String username,@NotBlank String displayName,@Size(min=8)String password){}public record Update(@NotBlank String displayName,boolean active,@Size(min=8)String newPassword){}
 @GetMapping List<Salesperson> list(){return db.sql("select id,username,display_name,active from amcservice.users where role='SALESPERSON' and tenant_id is null order by active desc,display_name").query(Salesperson.class).list();}
 @PostMapping@ResponseStatus(HttpStatus.CREATED)@Transactional Salesperson create(@Valid@RequestBody Create r){var id=UUID.randomUUID();try{db.sql("insert into amcservice.users(id,username,password_hash,display_name,role) values(:id,:username,:password,:name,'SALESPERSON')").param("id",id).param("username",r.username().trim()).param("password",passwords.encode(r.password())).param("name",r.displayName().trim()).update();}catch(Exception e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Salesperson user ID already exists");}return new Salesperson(id,r.username().trim(),r.displayName().trim(),true);}
 @PutMapping("/{id}")@Transactional Salesperson update(@PathVariable UUID id,@Valid@RequestBody Update r){if(db.sql("update amcservice.users set display_name=:name,active=:active where id=:id and role='SALESPERSON' and tenant_id is null").param("name",r.displayName().trim()).param("active",r.active()).param("id",id).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Salesperson not found");if(r.newPassword()!=null&&!r.newPassword().isBlank())db.sql("update amcservice.users set password_hash=:password where id=:id").param("password",passwords.encode(r.newPassword())).param("id",id).update();var username=db.sql("select username from amcservice.users where id=:id").param("id",id).query(String.class).single();return new Salesperson(id,username,r.displayName().trim(),r.active());}
}
